changeSet.sql:
ALTER TABLE payouts ADD COLUMN tranche varchar(64) NOT NULL DEFAULT 'SALE';
DROP INDEX uq_payouts_one_live_per_part;
CREATE UNIQUE INDEX uq_payouts_one_live_per_tranche_part ON payouts (transaction_id, tranche, part_number)
    WHERE status IN ('SENDING', 'AWAITING_OTP', 'PENDING', 'SUCCESS') AND deleted = false;
COMMENT ON COLUMN payouts.tranche IS
    'SALE (outright: the whole price), SHARE:<payment id> (the developer''s share of one plan payment) or RELEASE (what HomeTrue held, at completion).';

changeSet.rollback:
DROP INDEX uq_payouts_one_live_per_tranche_part;
CREATE UNIQUE INDEX uq_payouts_one_live_per_part ON payouts (transaction_id, part_number)
    WHERE status IN ('SENDING', 'AWAITING_OTP', 'PENDING', 'SUCCESS') AND deleted = false;
ALTER TABLE payouts DROP COLUMN tranche;
